def adopt_publications(apps, schema_editor):
    tables = set(schema_editor.connection.introspection.table_names())
    for name in (
        "App",
        "AppOperation",
        "BotAPI",
        "BotType",
        "ConversationStats",
        "LegacyMarket",
        "PublicationCandidate",
        "ShareRecord",
        "WorkflowBot",
        "Publication",
        "Approval",
        "PublicRunGrant",
    ):
        model = apps.get_model("publishing", name)
        if model._meta.db_table not in tables:
            schema_editor.create_model(model)
            continue
        with schema_editor.connection.cursor() as cursor:
            columns = {
                column.name
                for column in schema_editor.connection.introspection.get_table_description(
                    cursor, model._meta.db_table
                )
            }
        for field in model._meta.local_fields:
            if field.column in columns:
                continue
            addition = field.clone()
            addition.set_attributes_from_name(field.name)
            addition.model = model
            addition.null = True
            addition.default = models.NOT_PROVIDED
            addition.db_default = models.NOT_PROVIDED
            schema_editor.add_field(model, addition)
            if field.has_default():
                quote = schema_editor.quote_name
                schema_editor.execute(
                    f"UPDATE {quote(model._meta.db_table)} SET {quote(field.column)} = %s",
                    [field.get_db_prep_save(field.get_default(), schema_editor.connection)],
                )
    category = apps.get_model("publishing", "BotType")
    for key, name, english, order in [
        (10, "工作", "Workplace", 10),
        (13, "学习", "Learning", 20),
        (14, "写作", "Writing", 30),
        (15, "编程", "Programming", 40),
        (17, "生活", "Lifestyle", 50),
        (39, "健康", "Health", 60),
        (24, "其他", "Other", 100),
    ]:
        category.objects.using(schema_editor.connection.alias).get_or_create(
            type_key=key,
            defaults={
                "type_name": name,
                "type_name_en": english,
                "order_num": order,
                "show_index": int(key != 24),
                "icon": "",
            },
        )


